catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }
    if (!newValue) {
        g_form.setValue('unit_price', '0.00');
        g_form.setValue('line_total', '0.00');
        return;
    }

    var ga = new GlideAjax('SupplyItemAjax');
    ga.addParam('sysparm_name', 'getItemPrice');
    ga.addParam('sysparm_item_id', newValue);
    ga.getXMLAnswer(function(price) {
        var unitPrice = parseFloat(price) || 0;
        var qty = parseInt(g_form.getValue('quantity') || 1, 10);
        g_form.setValue('unit_price', unitPrice.toFixed(2));
        g_form.setValue('line_total', (unitPrice * qty).toFixed(2));
    });
}
